using namespace std;
void dfs(vector<vector<int>>& graph, int node, vector<int>& colors, int* color_cnt,
int curr_color) {
    colors[node] = curr_color;
    color_cnt[curr_color]++;
    for (int neighbor : graph[node]) {
        if (colors[neighbor] == -1) {
            dfs(graph, neighbor, colors, color_cnt, curr_color ^ 1);
        }
    }
}
pair<int, int> find_b_school_students(int N, vector<pair<int, int>>& connections) {
    vector<vector<int>> graph(N + 1);
    for (const auto& connection : connections) {
        graph[connection.first].push_back(connection.second);
        graph[connection.second].push_back(connection.first);
    }
    vector<int> colors(N + 1, -1);
    int min_ans = 0;
    for (int i = 1; i <= N; ++i) {
        if (colors[i] == -1) {
            int color_cnt[2] = {0, 0};
            dfs(graph, i, colors, color_cnt, 0);
            min_ans += min(color_cnt[0], color_cnt[1]);
        }
    }
    return make_pair(min_ans, N - min_ans);
}
int main() {
    int N, M;
    cin >> N >> M;
    vector<pair<int, int>> connections(M);
    for (int i = 0; i < M; ++i) {
        cin >> connections[i].first >> connections[i].second;
    }
    pair<int, int> b_students = find_b_school_students(N, connections);
    cout << b_students.first << " " << b_students.second << endl;
    return 0;
}

#include <cstdio>
#include <algorithm>
#include <map>
using namespace std;
const int N = 505;
int n, m;
int val[N][N];
int vis[N][N];
int xmin, xmax, ymin, ymax;
int posx[N * N], posy[N * N], cnt;
int idx[N * N];
bool isend[3 * N * N];
map <int, int> ch[3 * N * N];
int root, ncnt;
int ans;
void dfs(int x, int y, int c)
{
    if (x < 1 || x > n || y < 1 || y > m)
        return;
    if (vis[x][y])
        return;
    if (val[x][y] != c)
        return;
    vis[x][y] = 1;
    xmin = min(xmin, x), xmax = max(xmax, x);
    ymin = min(ymin, y), ymax = max(ymax, y);
    posx[++cnt] = x;
    posy[cnt] = y;
    dfs(x - 1, y, c);
    dfs(x + 1, y, c);
    dfs(x, y - 1, c);
    dfs(x, y + 1, c);
}
void go(int &n, int v)
{
    if (!ch[n].count(v))
        ch[n][v] = ++ncnt;
    n = ch[n][v];
    return;
}
void work(int x, int y)
{
    cnt = 0;
    xmin = n, xmax = 1;
    ymin = m, ymax = 1;
    dfs(x, y, val[x][y]);
    for (int i = 1; i <= cnt; i++)
        idx[i] = (posx[i] - xmin) * (ymax - ymin + 1) + (posy[i] - ymin);
    sort(idx + 1, idx + cnt + 1);
    int cur = root;
    int lascnt = ncnt;
    go(cur, xmax - xmin + 1);
    go(cur, ymax - ymin + 1);
    for (int i = 1; i <= cnt; i++)
        go(cur, idx[i]);
    ans += (! isend[cur]);
    isend[cur] = 1;
}
int main()
{
    root = ++ncnt;
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            scanf("%d", &val[i][j]);
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (!vis[i][j])
                work(i, j);
    printf("%d\n", ans);
    return 0;
